# Standard library
import uuid

# Third-party
from sqlalchemy import ARRAY, Boolean, Integer, JSON, Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, TimestampMixin


class ExplorerSubPlanConditions(TimestampMixin, Base):
    __tablename__ = "explorer_sub_plan_conditions"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    equipment_required: Mapped[dict | None] = mapped_column(
        JSON,
        description=(
            "JSONB list of mandatory equipment items needed for the route "
            "(e.g. crampons, harness, helmet)."
        ),
    )
    equipment_optional: Mapped[dict | None] = mapped_column(
        JSON,
        description=(
            "JSONB list of recommended but not mandatory equipment items for "
            "the route."
        ),
    )
    permit_required: Mapped[bool | None] = mapped_column(
        Boolean,
        description=(
            "Whether a permit or authorization is required to access or "
            "traverse this route."
        ),
    )
    permit_info: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "Details about permit requirements in the default language "
            "(English), including where and how to obtain them."
        ),
    )
    permit_info_de: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "German (de) translation of the permit requirement details."
        ),
    )
    permit_info_pl: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "Polish (pl) translation of the permit requirement details."
        ),
    )
    guide_recommended: Mapped[bool | None] = mapped_column(
        Boolean,
        description=(
            "Whether hiring a professional mountain guide is recommended for "
            "this route."
        ),
    )
    min_age: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Minimum recommended age in years for participants on this route."
        ),
    )
    max_group_size: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Maximum recommended group size for safety or regulatory reasons "
            "on this route."
        ),
    )
    best_months = mapped_column(
        ARRAY(Integer),
        nullable=True,
        description=(
            "PostgreSQL array of month numbers (1-12) indicating the best "
            "months to attempt this route based on seasonal conditions."
        ),
    )
    best_months_note: Mapped[str | None] = mapped_column(
        Text,
        description=(
            "Explanatory note in the default language (English) about "
            "seasonal timing recommendations for this route."
        ),
    )
    best_months_note_de: Mapped[str | None] = mapped_column(
        Text,
        description="German (de) translation of the seasonal timing note.",
    )
    best_months_note_pl: Mapped[str | None] = mapped_column(
        Text,
        description="Polish (pl) translation of the seasonal timing note.",
    )
